import org.apache.commons.lang3.reflect.TypeUtils;
import java.lang.reflect.*;
import java.util.*;

public class Scratch {
    static class NumBox<N extends Number> {}
    static class IntBox extends NumBox<Integer> {}

    public static void main(String[] args) throws Exception {
        // isAssignable raw to parameterized
        ParameterizedType listOfString = TypeUtils.parameterize(List.class, String.class);
        System.out.println("ArrayList.class isAssignable List<String>: " + TypeUtils.isAssignable(ArrayList.class, listOfString));
        System.out.println("List<String> isAssignable List<String>: " + TypeUtils.isAssignable(listOfString, TypeUtils.parameterize(List.class, String.class)));
        System.out.println("List<Integer> isAssignable List<String>: " + TypeUtils.isAssignable(TypeUtils.parameterize(List.class, Integer.class), listOfString));
        System.out.println("List<String> isAssignable List<? extends CharSequence>: " + TypeUtils.isAssignable(listOfString, TypeUtils.parameterize(List.class, TypeUtils.wildcardType().withUpperBounds(CharSequence.class).build())));

        // determineTypeArguments
        ParameterizedType collOfString = TypeUtils.parameterize(Collection.class, String.class);
        Map<TypeVariable<?>, Type> m = TypeUtils.determineTypeArguments(ArrayList.class, collOfString);
        System.out.println("determineTypeArguments map: " + m);
        System.out.println("  E -> " + m.get(ArrayList.class.getTypeParameters()[0]));

        System.out.println("determineTypeArguments incompatible: " + TypeUtils.determineTypeArguments(String.class, collOfString));

        // getTypeArguments(Type,Class)
        Map<TypeVariable<?>, Type> m2 = TypeUtils.getTypeArguments(String.class, Comparable.class);
        System.out.println("String->Comparable: " + m2);
        System.out.println("String->List: " + TypeUtils.getTypeArguments(String.class, List.class));

        // getRawType with TypeVariable
        TypeVariable<?> listE = List.class.getTypeParameters()[0];
        System.out.println("getRawType(E, List<String>): " + TypeUtils.getRawType(listE, listOfString));
        System.out.println("getRawType(E, null-assigning): " + TypeUtils.getRawType(listE, null));

        // getRawType GenericArrayType
        GenericArrayType gat = TypeUtils.genericArrayType(String.class);
        System.out.println("getRawType(GAT<String>, null): " + TypeUtils.getRawType(gat, null));

        // custom Type impl -> IllegalArgumentException
        Type weird = new Type() {};
        try {
            TypeUtils.getRawType(weird, null);
            System.out.println("no exception!");
        } catch (IllegalArgumentException e) {
            System.out.println("IAE as expected: " + e.getMessage());
        }

        // normalizeUpperBounds
        Type[] bounds = TypeUtils.normalizeUpperBounds(new Type[]{Number.class, Integer.class});
        System.out.println("normalizeUpperBounds: " + Arrays.toString(bounds));

        // wildcard toString
        System.out.println("WILDCARD_ALL toString: '" + TypeUtils.toString(TypeUtils.WILDCARD_ALL) + "'");
        WildcardType wSuper = TypeUtils.wildcardType().withLowerBounds(String.class).build();
        System.out.println("wSuper toString: '" + TypeUtils.toString(wSuper) + "'");
        WildcardType wExtends = TypeUtils.wildcardType().withUpperBounds(Number.class).build();
        System.out.println("wExtends toString: '" + TypeUtils.toString(wExtends) + "'");

        // toLongString
        System.out.println("toLongString(List.E): " + TypeUtils.toLongString(listE));

        // parameterize toString
        System.out.println("List<String> toString: " + TypeUtils.toString(listOfString));

        // typesSatisfyVariables
        Map<TypeVariable<?>, Type> tv = new HashMap<TypeVariable<?>, Type>();
        tv.put(NumBox.class.getTypeParameters()[0], Integer.class);
        System.out.println("typesSatisfyVariables(N=Integer): " + TypeUtils.typesSatisfyVariables(tv));
        Map<TypeVariable<?>, Type> tv2 = new HashMap<TypeVariable<?>, Type>();
        tv2.put(NumBox.class.getTypeParameters()[0], String.class);
        System.out.println("typesSatisfyVariables(N=String): " + TypeUtils.typesSatisfyVariables(tv2));

        // isInstance
        System.out.println("isInstance(\"x\", String.class): " + TypeUtils.isInstance("x", String.class));
        System.out.println("isInstance(5, String.class): " + TypeUtils.isInstance(5, String.class));
        System.out.println("isInstance(null, String.class): " + TypeUtils.isInstance(null, String.class));
        System.out.println("isInstance(null, int.class): " + TypeUtils.isInstance(null, int.class));

        // containsTypeVariables
        System.out.println("containsTypeVariables(String.class): " + TypeUtils.containsTypeVariables(String.class));
        System.out.println("containsTypeVariables(List.class): " + TypeUtils.containsTypeVariables(List.class));
        System.out.println("containsTypeVariables(listOfString): " + TypeUtils.containsTypeVariables(listOfString));
        System.out.println("containsTypeVariables(E): " + TypeUtils.containsTypeVariables(listE));

        // getArrayComponentType
        System.out.println("getArrayComponentType(int[].class): " + TypeUtils.getArrayComponentType(int[].class));
        System.out.println("getArrayComponentType(String.class): " + TypeUtils.getArrayComponentType(String.class));
        System.out.println("getArrayComponentType(GAT): " + TypeUtils.getArrayComponentType(gat));

        // isArrayType
        System.out.println("isArrayType(int[].class): " + TypeUtils.isArrayType(int[].class));
        System.out.println("isArrayType(String.class): " + TypeUtils.isArrayType(String.class));
        System.out.println("isArrayType(gat): " + TypeUtils.isArrayType(gat));
        System.out.println("isArrayType(null): " + TypeUtils.isArrayType(null));

        // unrollVariables
        Map<TypeVariable<?>, Type> uv = new HashMap<TypeVariable<?>, Type>();
        uv.put(NumBox.class.getTypeParameters()[0], Integer.class);
        ParameterizedType pNumBoxN = TypeUtils.parameterize(NumBox.class, NumBox.class.getTypeParameters()[0]);
        System.out.println("unrollVariables NumBox<N> with N=Integer: " + TypeUtils.unrollVariables(uv, pNumBoxN));
        System.out.println("unrollVariables null map, Integer.class: " + TypeUtils.unrollVariables(null, Integer.class));
    }
}
EOF
