import org.apache.commons.lang3.reflect.TypeUtils;
import java.lang.reflect.*;
import java.util.*;

public class _scratch_Debug {
    static class NumBox<N extends Number> {}

    public static void main(String[] args) throws Exception {
        TypeVariable<?> n1 = NumBox.class.getTypeParameters()[0];
        Map<TypeVariable<?>, Type> uv = new HashMap<TypeVariable<?>, Type>();
        uv.put(n1, Integer.class);
        System.out.println("map contains n1: " + uv.containsKey(n1));
        ParameterizedType p = TypeUtils.parameterize(NumBox.class, n1);
        Type argAt0 = p.getActualTypeArguments()[0];
        System.out.println("argAt0 equals n1: " + argAt0.equals(n1));
        System.out.println("uv.get(argAt0): " + uv.get(argAt0));
        Type result = TypeUtils.unrollVariables(uv, p);
        System.out.println("result: " + result);
    }
}
JAVAEOF
javac -cp target/classes -d "$TMPDIR" _scratch_Debug.java && java -cp "target/classes:$TMPDIR" _scratch_Debug
